<?php
/** TNTS v5.7 Phase 4.7.4 — read-only stock and ICS source-batch audit. */
require_once __DIR__.'/includes/auth.php';
$me=require_role(['supply_officer','tvl_head']);
$pdo=db();
$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$today=date('Y-m-d');
$problems=[];$notices=[];
function audit_rows(PDO $pdo,string $sql,array $params=[]):array {$s=$pdo->prepare($sql);$s->execute($params);return $s->fetchAll(PDO::FETCH_ASSOC);}
function audit_add(array &$out,string $level,string $title,string $detail,string $ref=''):void {$out[]=['level'=>$level,'title'=>$title,'detail'=>$detail,'ref'=>$ref];}
try {
$master=audit_rows($pdo,"SELECT i.item_id,i.item_name,i.item_category,i.quantity, COALESCE((SELECT SUM(b.received_qty) FROM inventory_receipt_batches b WHERE b.inventory_item_id=i.item_id),0) received, COALESCE((SELECT SUM(ii.qty_issued) FROM ics_items ii WHERE ii.item_id=i.item_id),0) issued, COALESCE((SELECT SUM(ii.qty_returned) FROM ics_items ii WHERE ii.item_id=i.item_id),0) returned, COALESCE((SELECT SUM(w.quantity) FROM inventory_withdrawals w WHERE w.item_id=i.item_id),0) withdrawn FROM inventory_items i ORDER BY i.item_name,i.item_id");
$batch=audit_rows($pdo,"SELECT b.batch_id,b.inventory_item_id,i.item_name,b.batch_number,b.expiration_date,b.received_qty,b.course_id,COALESCE(SUM(a.qty_issued),0) issued,COALESCE(SUM(a.qty_returned),0) returned,COALESCE(SUM(a.qty_serviceable_returned),0) serviceable_returned,COALESCE(SUM(a.qty_issued-a.qty_returned),0) outstanding FROM inventory_receipt_batches b JOIN inventory_items i ON i.item_id=b.inventory_item_id LEFT JOIN ics_batch_allocations a ON a.batch_id=b.batch_id GROUP BY b.batch_id,b.inventory_item_id,i.item_name,b.batch_number,b.expiration_date,b.received_qty,b.course_id ORDER BY i.item_name,b.batch_id");
$ics=audit_rows($pdo,"SELECT ii.ics_item_id,c.ics_number,c.teacher_id,u.full_name AS holder,i.item_name,ii.item_id,ii.qty_issued,ii.qty_returned,COALESCE(SUM(a.qty_issued),0) linked_issued,COALESCE(SUM(a.qty_returned),0) linked_returned FROM ics_items ii JOIN ics c ON c.ics_id=ii.ics_id JOIN inventory_items i ON i.item_id=ii.item_id JOIN users u ON u.user_id=c.teacher_id LEFT JOIN ics_batch_allocations a ON a.ics_item_id=ii.ics_item_id GROUP BY ii.ics_item_id,c.ics_number,c.teacher_id,u.full_name,i.item_name,ii.item_id,ii.qty_issued,ii.qty_returned ORDER BY c.ics_number,ii.ics_item_id");
$mismatched=audit_rows($pdo,"SELECT a.allocation_id,a.ics_item_id,a.batch_id,i1.item_name AS issued_item,i2.item_name AS receipt_item FROM ics_batch_allocations a JOIN ics_items ii ON ii.ics_item_id=a.ics_item_id JOIN inventory_receipt_batches b ON b.batch_id=a.batch_id JOIN inventory_items i1 ON i1.item_id=ii.item_id JOIN inventory_items i2 ON i2.item_id=b.inventory_item_id WHERE ii.item_id<>b.inventory_item_id");
$returns=audit_rows($pdo,"SELECT a.allocation_id,a.ics_item_id,a.batch_id,a.qty_issued,a.qty_returned,a.qty_serviceable_returned,COALESCE(SUM(r.qty_serviceable+r.qty_for_repair+r.qty_damaged),0) documented_returned,COALESCE(SUM(r.qty_serviceable),0) documented_serviceable FROM ics_batch_allocations a LEFT JOIN ics_batch_return_lines r ON r.allocation_id=a.allocation_id GROUP BY a.allocation_id,a.ics_item_id,a.batch_id,a.qty_issued,a.qty_returned,a.qty_serviceable_returned");
foreach($mismatched as $r){audit_add($problems,'danger','Batch belongs to a different item','ICS item: '.$r['issued_item'].'; receipt item: '.$r['receipt_item'],'Allocation #'.$r['allocation_id']);}
foreach($master as $r){if((int)$r['quantity']!==(int)$r['received'])audit_add($notices,'warning','Master total differs from accepted batch receipts','Master quantity '.(int)$r['quantity'].'; linked receipt quantity '.(int)$r['received'].'. Verify historical/imported stock before correcting.',$r['item_name'].' (#'.$r['item_id'].')');}
foreach($ics as $r){$ref=$r['ics_number'].' / '.$r['item_name'].' / line #'.$r['ics_item_id'];if((int)$r['qty_returned']>(int)$r['qty_issued'])audit_add($problems,'danger','ICS returned quantity exceeds issued','Returned '.(int)$r['qty_returned'].' / issued '.(int)$r['qty_issued'],$ref);if((int)$r['linked_issued']>(int)$r['qty_issued'])audit_add($problems,'danger','Batch allocation exceeds ICS issue','Allocated '.(int)$r['linked_issued'].' / issued '.(int)$r['qty_issued'],$ref);if((int)$r['linked_returned']>(int)$r['qty_returned'])audit_add($problems,'danger','Batch returns exceed ICS recorded returns','Batch returned '.(int)$r['linked_returned'].' / ICS returned '.(int)$r['qty_returned'],$ref);if((int)$r['linked_issued']<(int)$r['qty_issued'])audit_add($notices,'info','ICS has legacy/unattributed source quantity','Unattributed original issuance: '.((int)$r['qty_issued']-(int)$r['linked_issued']).' unit(s). Never invent a batch.',$ref);}
foreach($returns as $r){if((int)$r['qty_returned']>(int)$r['qty_issued']||(int)$r['qty_serviceable_returned']>(int)$r['qty_returned'])audit_add($problems,'danger','Invalid allocation return totals','Check issued, returned and serviceable returned.','Allocation #'.$r['allocation_id']);if((int)$r['documented_returned']!==(int)$r['qty_returned']||(int)$r['documented_serviceable']!==(int)$r['qty_serviceable_returned'])audit_add($problems,'danger','Return line ledger mismatch','Return line sum '.(int)$r['documented_returned'].' versus allocation returned '.(int)$r['qty_returned'].'; serviceable '.(int)$r['documented_serviceable'].' versus '.(int)$r['qty_serviceable_returned'],'Allocation #'.$r['allocation_id']);}
foreach($batch as $r){$ref=$r['item_name'].' / batch #'.$r['batch_id'];$raw=(int)$r['received_qty']-(int)$r['issued']+(int)$r['serviceable_returned'];if($raw<0)audit_add($problems,'danger','Receipt batch over-allocated','Received '.(int)$r['received_qty'].', issued '.(int)$r['issued'].', verified reusable returns '.(int)$r['serviceable_returned'],$ref);if($r['expiration_date']!==null&&$r['expiration_date']<$today&&(int)$r['outstanding']>0)audit_add($notices,'warning','Expired stock still assigned to an ICS','Expired on '.$r['expiration_date'].'; '.(int)$r['outstanding'].' outstanding unit(s). Not disposed automatically.',$ref);if($r['expiration_date']!==null&&$r['expiration_date']<$today&&$raw>0)audit_add($notices,'warning','Expired stock still in central receipt balance','Up to '.$raw.' raw batch units recorded; no issuance should be allowed. Other legacy reservations may apply.',$ref);}
}catch(Throwable $ex){http_response_code(500);$pageTitle='Batch Reconciliation';$active='batch_reconciliation.php';require __DIR__.'/includes/header.php';echo '<div class="card"><h2>Audit could not run</h2><p>The installation may be missing a Phase 4.7 migration. Check that Phase 4.7.1 through 4.7.3 were installed in order. No records were changed.</p><pre>'.e($ex->getMessage()).'</pre></div>';require __DIR__.'/includes/footer.php';exit;}
$pageTitle='Batch Reconciliation';$active='batch_reconciliation.php';require __DIR__.'/includes/header.php';
?>
<div class="content-header"><h2>Batch Reconciliation &amp; Regression Audit</h2><p>Read-only checks of ICS allocations, delivery batches, returns, expiration, and historical records. No balances are modified.</p></div>
<div class="card" style="margin-bottom:18px"><p><strong>Run date:</strong> <?= e($today) ?> &nbsp; · &nbsp; <strong>Master items:</strong> <?= count($master) ?> &nbsp; · &nbsp; <strong>Receipt batches:</strong> <?= count($batch) ?> &nbsp; · &nbsp; <strong>ICS lines:</strong> <?= count($ics) ?></p><p><strong>Critical inconsistencies:</strong> <?= count($problems) ?> &nbsp; · &nbsp; <strong>Notices / reconciliation work:</strong> <?= count($notices) ?></p><p class="muted">A count of zero critical inconsistencies does not certify the database. It means these specific checks found no contradiction. An expired item must still follow the school's disposal process.</p></div>
<?php foreach([['Critical inconsistencies',$problems],['Notices / manual review',$notices]] as $section): ?>
<div class="card" style="margin-bottom:18px"><h3><?= e($section[0]) ?> (<?= count($section[1]) ?>)</h3><div class="table-wrap"><table class="table"><thead><tr><th>Finding</th><th>Reference</th><th>Explanation</th></tr></thead><tbody>
<?php foreach($section[1] as $p): ?><tr><td><strong><?= e($p['title']) ?></strong></td><td><?= e($p['ref']) ?></td><td><?= e($p['detail']) ?></td></tr><?php endforeach; ?>
<?php if(!$section[1]):?><tr><td colspan="3">No findings in this section.</td></tr><?php endif; ?></tbody></table></div></div><?php endforeach; ?>
<div class="card"><h3>Master stock reference</h3><p class="muted">Reference quantities only: issued and returned are historical totals. For supplies, distribution and physical retrieval follow separate rules; do not calculate central stock by subtracting returns without category checks.</p><div class="table-wrap"><table class="table"><thead><tr><th>Item</th><th>Category</th><th>Master qty</th><th>Batch receipts</th><th>Original ICS issued</th><th>Recorded ICS returns</th><th>Withdrawals</th></tr></thead><tbody><?php foreach($master as $r):?><tr><td><?= e($r['item_name']) ?></td><td><?= e($r['item_category']) ?></td><td><?= (int)$r['quantity'] ?></td><td><?= (int)$r['received'] ?></td><td><?= (int)$r['issued'] ?></td><td><?= (int)$r['returned'] ?></td><td><?= (int)$r['withdrawn'] ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<p class="muted" style="margin-top:16px">If a discrepancy appears, keep your backup and report its exact reference before changing stock. Phase 5 transfers must not proceed using inconsistent allocation balances.</p>
<?php require __DIR__.'/includes/footer.php'; ?>
